solution:
pub type Age = Int
  invariant: this >= 0;
  invariant: this <= 150;

fn can_vote(age: &Age) -> Bool {
  return age >= 18;
}

fn main() -> Int {
  let voter_age: Age = 25;
  if can_vote(&voter_age) { return 1; }
  return 0;
}
